{
  "allowed_targets": {
    "assumption_ids": [],
    "constraint_ids": [
      "L-C1",
      "L-C2",
      "L-C3"
    ],
    "has_pivotal_assumption": true,
    "step_rules": [
      "compute_action_impact",
      "check_cash_reserve_floor",
      "check_runway_floor",
      "check_initiative_budget",
      "check_hire_objective"
    ]
  },
  "decision_context": {
    "action": {
      "count": 5,
      "fully_loaded_cost_per_year": 200000.0,
      "role": "engineer",
      "type": "hire"
    },
    "company": {
      "constraints": [
        {
          "id": "L-C1",
          "kind": "hard",
          "note": "finance policy",
          "semi_formal": "cash_balance(t) >= 500000  for all t",
          "statement": "Cash balance must never fall below the $500,000 operating reserve."
        },
        {
          "id": "L-C2",
          "kind": "hard",
          "note": "board mandate; this is a maintained invariant, not a one-time check",
          "semi_formal": "runway_months(t) = cash_balance(t)/net_burn(t) >= 6  for all t",
          "statement": "At least 6 months of forward runway must be MAINTAINED at all times."
        },
        {
          "id": "L-C3",
          "kind": "hard",
          "note": null,
          "semi_formal": "initiative_budget <= 1500000",
          "statement": "Any single new initiative's budget must be <= $1,500,000."
        },
        {
          "id": "L-C4",
          "kind": "hard",
          "note": "LTV (simple) = arpu_monthly * gross_margin / monthly_churn_rate",
          "semi_formal": "ltv_cac(channel) >= 3.0",
          "statement": "A growth channel may only be scaled if its LTV/CAC >= 3.0."
        }
      ],
      "facts": {
        "arpu_monthly": {
          "note": null,
          "unit": "USD/customer/mo",
          "value": 1400
        },
        "blended_cac": {
          "note": null,
          "unit": "USD/customer",
          "value": 12000
        },
        "cash_balance": {
          "note": null,
          "unit": "USD",
          "value": 3200000
        },
        "customers": {
          "note": null,
          "unit": "customers",
          "value": 300
        },
        "gross_margin": {
          "note": null,
          "unit": "fraction",
          "value": 0.8
        },
        "headcount": {
          "note": null,
          "unit": "people",
          "value": 45
        },
        "monthly_churn_rate": {
          "note": null,
          "unit": "fraction of MRR/mo",
          "value": 0.025
        },
        "monthly_new_bookings_mrr": {
          "note": "gross new bookings before churn",
          "unit": "USD MRR/mo",
          "value": 40000
        },
        "mrr": {
          "note": null,
          "unit": "USD/mo",
          "value": 420000
        },
        "net_monthly_burn": {
          "note": "current runway = cash / burn = 8 months",
          "unit": "USD/mo",
          "value": 400000
        }
      },
      "id": "lumen",
      "name": "Lumen Labs",
      "sector": "B2B SaaS (analytics)"
    },
    "id": "D1",
    "objective": "Increase product velocity while remaining within all hard constraints.",
    "proposal": "Hire 5 additional engineers immediately to accelerate the roadmap.",
    "stated_assumptions": []
  },
  "verification_result": {
    "binding_constraints": [
      {
        "id": "L-C1",
        "pass": true,
        "why": "post-action cash 3200000 >= reserve floor 500000"
      },
      {
        "id": "L-C2",
        "pass": true,
        "why": "post-action runway 6.6207 months >= floor 6"
      },
      {
        "id": "L-C3",
        "pass": true,
        "why": "initiative budget 1000000 <= cap 1500000"
      }
    ],
    "classification": "UNDECIDABLE",
    "derivation": [
      {
        "inputs": {
          "action_type": "hire"
        },
        "result": {
          "cash_outflow": 0,
          "initiative_budget": 1000000,
          "monthly_burn_delta": 83333.3333
        },
        "rule": "compute_action_impact"
      },
      {
        "inputs": {
          "cash_outflow": 0,
          "constraint_id": "L-C1",
          "current_cash_balance": 3200000
        },
        "result": {
          "passed": true,
          "post_cash_balance": 3200000,
          "threshold": 500000
        },
        "rule": "check_cash_reserve_floor"
      },
      {
        "inputs": {
          "constraint_id": "L-C2",
          "post_action_cash_balance": 3200000,
          "post_action_net_monthly_burn": 483333.3333
        },
        "result": {
          "passed": true,
          "post_action_runway_months": 6.6207,
          "threshold": 6
        },
        "rule": "check_runway_floor"
      },
      {
        "inputs": {
          "constraint_id": "L-C3"
        },
        "result": {
          "initiative_budget": 1000000,
          "passed": true,
          "threshold": 1500000
        },
        "rule": "check_initiative_budget"
      },
      {
        "inputs": {
          "current_headcount": 45,
          "objective": "Increase product velocity while remaining within all hard constraints."
        },
        "result": {
          "annual_cost_per_hire": 200000,
          "headcount_added": 5,
          "objective_forced_by_facts": false
        },
        "rule": "check_hire_objective"
      }
    ],
    "flip_threshold": "Product-velocity improvement threshold is not quantified in the provided facts.",
    "load_bearing_assumptions": [],
    "pivotal_assumption": "The five additional engineers materially increase product velocity enough to justify the hire.",
    "refutation": {
      "attempted": true,
      "failure_conditions": "objective depends on unquantified engineering productivity and delivery impact"
    },
    "refuted_if": "the added engineering capacity does not produce a material velocity gain",
    "supported_if": "the added engineering capacity yields a material product-velocity gain"
  }
}
